                    padding: 10px 16px;
                    font-size: 13px;
                }
            }
        `;
        document.head.appendChild(style);
    }

    // 显示安装按钮
    function showInstallButton() {
        if (installButton) return;

        addStyles();
        installButton = createInstallButton();
        document.body.appendChild(installButton);

        // 添加脉搏动画
        setTimeout(() => {
            installButton.classList.add('pulse');
        }, 1000);

