#### 关联关系注解

##### @OneToOne - 一对一关系
```java
/**
 * 一对一关系：一个用户对应一个用户详情
 */

// 主表（拥有外键的一方）
@Entity
public class User {
    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    private String username;

    /**
     * @OneToOne: 一对一关系
     * @JoinColumn: 指定外键列
     */
    @OneToOne(cascade = CascadeType.ALL, fetch = FetchType.LAZY)
    @JoinColumn(name = "profile_id", referencedColumnName = "id")
    private UserProfile profile;

    // 构造器、getter、setter...
}

// 从表
@Entity
public class UserProfile {
    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    private String firstName;
    private String lastName;
    private String bio;
    private String avatarUrl;

    // 双向关联：从UserProfile也能访问User
    @OneToOne(mappedBy = "profile") // mappedBy指向User类中的profile字段
    private User user;

    // 构造器、getter、setter...
}

// 使用示例
@Service
public class UserService {

    @Autowired
    private UserRepository userRepository;

    public User createUserWithProfile(String username, String firstName, String lastName) {
        // 创建用户详情
        UserProfile profile = new UserProfile();
        profile.setFirstName(firstName);
        profile.setLastName(lastName);

        // 创建用户
        User user = new User();
        user.setUsername(username);
        user.setProfile(profile);

        // 设置双向关联
        profile.setUser(user);

        // 由于设置了cascade = CascadeType.ALL，保存user时会自动保存profile
        return userRepository.save(user);
    }
}
```

##### @OneToMany - 一对多关系
```java
/**
 * 一对多关系：一个用户可以有多个订单
 */

// "一"的一方：User
@Entity
public class User {
    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    private String username;

    /**
     * @OneToMany: 一对多关系
     * mappedBy: 指向Order类中的user字段（表示外键在Order表中）
     * cascade: 级联操作（保存用户时自动处理订单）
     * fetch: 加载策略（LAZY表示需要时才加载订单列表）
     */
    @OneToMany(mappedBy = "user", cascade = CascadeType.ALL, fetch = FetchType.LAZY)
    private List<Order> orders = new ArrayList<>();

    // 便利方法：添加订单
    public void addOrder(Order order) {
        orders.add(order);
        order.setUser(this); // 设置双向关联
    }

    // 便利方法：移除订单
    public void removeOrder(Order order) {
        orders.remove(order);
        order.setUser(null);
    }
}

// "多"的一方：Order
@Entity
public class Order {
    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    private BigDecimal totalAmount;
    private LocalDateTime orderTime;

    /**
     * @ManyToOne: 多对一关系（从Order的角度看，多个订单对应一个用户）
     * @JoinColumn: 指定外键列名
     */
    @ManyToOne(fetch = FetchType.LAZY)
    @JoinColumn(name = "user_id", nullable = false)
    private User user;

    // 构造器、getter、setter...
}

// 使用示例
@Service
public class OrderService {

    public Order createOrder(Long userId, BigDecimal amount) {
        User user = userRepository.findById(userId)
            .orElseThrow(() -> new UserNotFoundException("用户不存在"));

        Order order = new Order();
        order.setTotalAmount(amount);
        order.setOrderTime(LocalDateTime.now());

        // 建立关联关系
        user.addOrder(order);

        return orderRepository.save(order);
    }

    // 获取用户的所有订单
    public List<Order> getUserOrders(Long userId) {
        User user = userRepository.findById(userId)
            .orElseThrow(() -> new UserNotFoundException("用户不存在"));

        // 由于使用了LAZY加载，这里会触发数据库查询
        return user.getOrders();
    }
}
```

##### @ManyToMany - 多对多关系
```java
/**
 * 多对多关系：用户和角色的关系（一个用户可以有多个角色，一个角色可以分配给多个用户）
 */

// 主控方：User
@Entity
public class User {
    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    private String username;

    /**
     * @ManyToMany: 多对多关系
     * @JoinTable: 指定中间表的信息
     */
    @ManyToMany(cascade = {CascadeType.PERSIST, CascadeType.MERGE}, fetch = FetchType.LAZY)
    @JoinTable(
        name = "user_roles",                    // 中间表名
        joinColumns = @JoinColumn(name = "user_id"),     // 当前实体的外键列
        inverseJoinColumns = @JoinColumn(name = "role_id") // 关联实体的外键列
    )
    private Set<Role> roles = new HashSet<>();

    // 便利方法：添加角色
    public void addRole(Role role) {
        roles.add(role);
        role.getUsers().add(this);
    }

    // 便利方法：移除角色
    public void removeRole(Role role) {
        roles.remove(role);
        role.getUsers().remove(this);
    }
}

// 被控方：Role
