    @DecimalMax(value = "999999.99", message = "价格不能超过999999.99")
    @Digits(integer = 6, fraction = 2, message = "价格格式不正确，最多6位整数和2位小数")
    private BigDecimal price;

    @Min(value = 0, message = "库存数量不能为负数")
    @Max(value = 10000, message = "库存数量不能超过10000")
