@Configuration
public class RedisConfig {

    @Value("${REDIS_HOST:${spring.redis.host:localhost}}")
    private String redisHost;

    @Value("${REDIS_PORT:${spring.redis.port:6379}}")
    private int redisPort;

    @Bean
